const UX_GENERAL_THEORY = [
  { id: 201, category: "UX Principles", difficulty: "Easy", question: "What is the primary focus of 'User-Centered Design' (UCD)?", options: ["Prioritizing business revenue over user needs", "Involving users throughout the design process to ensure the product meets their needs", "Creating the most visually complex interfaces possible", "Designing strictly for mobile devices first"], answerIndex: 1, explanation: "User-Centered Design is an iterative process where designers focus on the users and their needs in each phase of the design process.", example: "Conducting user interviews before sketching any screens." },
  { id: 202, category: "UI Components", difficulty: "Medium", question: "Which UI element is best suited for mutually exclusive choices where all options need to be visible?", options: ["Checkboxes", "Radio Buttons", "Dropdown Menus", "Toggle Switches"], answerIndex: 1, explanation: "Radio buttons are standard for mutually exclusive options when you want the user to see all available choices at a glance.", example: "Selecting a shipping method: Standard, Express, or Overnight." },
  { id: 203, category: "Accessibility", difficulty: "Hard", question: "What does the WCAG principle 'Operable' primarily ensure?", options: ["Users can perceive the information being presented", "Users can interact with all interface components and navigation", "Users can understand the information and operation of the user interface", "Content must be robust enough to be interpreted by various user agents"], answerIndex: 1, explanation: "Operable means that the interface cannot require interaction that a user cannot perform (e.g., ensuring full keyboard accessibility).", example: "Being able to navigate a complex form using only the Tab key." },
  { id: 204, category: "UX Research", difficulty: "Easy", question: "What is a 'Pain Point' in UX research?", options: ["A moment when the software crashes completely", "A specific problem or friction point that users experience during their journey", "The physical discomfort of using a mouse too much", "A feature that the development team finds difficult to code"], answerIndex: 1, explanation: "Pain points are frustrations or obstacles users face while trying to complete a goal.", example: "A multi-page checkout process that doesn't save the user's previously entered shipping address." },
  { id: 205, category: "Typography", difficulty: "Medium", question: "In typography, what is 'Kerning'?", options: ["The vertical space between lines of text", "The horizontal space between individual characters or letters", "The overall spacing across a block of text", "The thickness of the font strokes"], answerIndex: 1, explanation: "Kerning is the process of adjusting the spacing between two specific characters to achieve a visually pleasing result.", example: "Adjusting the space between a capital 'A' and 'V' so they don't look too far apart." },
  { id: 206, category: "Gestalt", difficulty: "Medium", question: "How does the Gestalt principle of 'Symmetry' affect user perception?", options: ["Users prefer asymmetrical designs for modern web apps", "Symmetrical elements are perceived as belonging together regardless of their distance", "The mind perceives symmetrical objects as forming around a center point, creating balance and stability", "Symmetry causes cognitive overload in complex interfaces"], answerIndex: 2, explanation: "Symmetry gives a feeling of solidity and order, helping users quickly understand the structure of a page.", example: "A balanced grid of product photos on an e-commerce landing page." },
  { id: 207, category: "Interaction Design", difficulty: "Easy", question: "What is the purpose of 'Breadcrumbs' in web navigation?", options: ["To track user data for analytics", "To leave a trail of cookies on the user's browser", "To show users their current location in the site hierarchy and allow them to navigate back", "To highlight the most popular pages on the site"], answerIndex: 2, explanation: "Breadcrumbs act as a secondary navigation scheme that reveals the user's location in a website or web application.", example: "Home > Electronics > Cameras > DSLR" },
  { id: 208, category: "UX Laws", difficulty: "Hard", question: "What is the 'Von Restorff Effect'?", options: ["Users recall the first and last items in a list better than middle items", "When multiple similar objects are present, the one that differs from the rest is most likely to be remembered", "Users' perception of time speeds up when they are engaged", "The more options presented, the longer it takes to make a decision"], answerIndex: 1, explanation: "Also known as the isolation effect, it predicts that an item that 'stands out like a sore thumb' is more likely to be remembered.", example: "Making the 'Upgrade to Pro' pricing tier a different, bolder color than the free and enterprise tiers." },
  { id: 209, category: "Prototyping", difficulty: "Medium", question: "What is the primary advantage of a 'Low-Fidelity' prototype?", options: ["It provides a realistic representation of the final product", "It contains production-ready code", "It allows for rapid iteration and focuses feedback on concepts and layout rather than visual details", "It can be published directly to an app store"], answerIndex: 2, explanation: "Low-fidelity prototypes (like paper sketches or simple wireframes) are cheap and quick to make, encouraging early structural feedback.", example: "Sketching a mobile app's flow on a whiteboard before opening Figma." },
  { id: 210, category: "Information Architecture", difficulty: "Easy", question: "What does 'Taxonomy' refer to in Information Architecture?", options: ["The visual hierarchy of fonts", "The classification and organization of content into logical groups and structures", "The physical layout of servers hosting the website", "The financial budget allocated for UX research"], answerIndex: 1, explanation: "Taxonomy is the science of classification. In UX, it's how you organize, group, and label content so it makes sense to users.", example: "Categorizing a blog into 'Design', 'Development', and 'Business' tags." },
  { id: 211, category: "Visual Design", difficulty: "Medium", question: "What is the '60-30-10 Rule' in color theory?", options: ["60% primary color, 30% secondary color, 10% accent color", "60% white space, 30% images, 10% text", "60% contrast, 30% brightness, 10% saturation", "60% background, 30% foreground, 10% interactive elements"], answerIndex: 0, explanation: "It's a classic design rule to create a balanced color palette. The primary color dominates, the secondary supports, and the accent draws attention to key elements.", example: "A dark mode app with a 60% dark grey background, 30% lighter grey panels, and a 10% vibrant orange for buttons." },
  { id: 212, category: "Usability Testing", difficulty: "Hard", question: "What is a 'Cognitive Walkthrough'?", options: ["A physical tour of the office space by users", "An automated script that clicks all buttons on a site", "A usability evaluation method where evaluators step through tasks from a user's perspective to identify usability issues", "A survey asking users about their mental health"], answerIndex: 2, explanation: "Evaluators ask a series of questions at each step of a task to see if a new user would know what to do.", example: "Experts reviewing a checkout flow step-by-step and asking 'Will the user notice the promo code field?'" },
  { id: 213, category: "UI Components", difficulty: "Easy", question: "What is a 'Modal' or 'Dialog' window?", options: ["A permanent sidebar navigation", "An overlay that requires users to interact with it before they can return to the main application", "A small tooltip that appears on hover", "A banner at the top of the page that can be ignored"], answerIndex: 1, explanation: "Modals interrupt the user's workflow to demand attention for a critical action or information.", example: "A popup asking 'Are you sure you want to delete this file?' with Confirm/Cancel buttons." },
  { id: 214, category: "UX Strategy", difficulty: "Medium", question: "What does 'MVP' stand for in product development?", options: ["Maximum Viable Product", "Minimum Viable Product", "Most Valuable Player", "Minimum Visual Prototype"], answerIndex: 1, explanation: "An MVP is a version of a new product which allows a team to collect the maximum amount of validated learning about customers with the least effort.", example: "Launching a ride-sharing app with just the ability to request a ride and pay, skipping advanced features like driver reviews or scheduled rides initially." },
  { id: 215, category: "Accessibility", difficulty: "Medium", question: "Why is 'Alt Text' important for images?", options: ["It makes the image load faster", "It applies SEO keywords to the image file name", "It provides a textual description of the image for screen readers and when the image fails to load", "It changes the color palette of the image to high contrast"], answerIndex: 2, explanation: "Alt text is crucial for visually impaired users who rely on screen readers to understand the content of images.", example: "Adding alt='A golden retriever playing catch in the park' to a photo." },
  { id: 216, category: "Heuristics", difficulty: "Hard", question: "Which of Nielsen's heuristics relates to providing users with 'Undo' and 'Redo' options?", options: ["Visibility of system status", "Match between system and the real world", "User control and freedom", "Error prevention"], answerIndex: 2, explanation: "User control and freedom emphasizes giving users an 'emergency exit' when they make a mistake.", example: "The 'Undo Send' feature in Gmail." },
  { id: 217, category: "Visual Design", difficulty: "Easy", question: "What is 'White Space' (or Negative Space) in design?", options: ["Only areas of the screen that are colored pure white", "The empty space between and around elements of a design layout", "The space reserved for advertising banners", "The area outside the user's screen resolution"], answerIndex: 1, explanation: "White space is the breathing room around elements. It doesn't have to be white; it's just unmarked space that helps structure the layout.", example: "The large empty area around the Google search bar on its homepage." },
  { id: 218, category: "UX Research", difficulty: "Medium", question: "What is 'A/B Testing'?", options: ["Testing a product with two different user personas simultaneously", "Comparing two versions of a webpage or app against each other to determine which one performs better", "Testing both the Alpha and Beta versions of software", "Asking users to rate a product from A to B"], answerIndex: 1, explanation: "A/B testing involves showing variation A to half your users and variation B to the other half, then measuring which achieves the goal better.", example: "Testing whether a red 'Buy Now' button gets more clicks than a green one." },
  { id: 219, category: "Typography", difficulty: "Medium", question: "What is the difference between Serif and Sans-Serif typefaces?", options: ["Serif fonts are only for digital screens; Sans-Serif are for print", "Serif fonts have small decorative strokes at the ends of letters; Sans-Serif fonts do not", "Serif fonts are bold; Sans-Serif fonts are light", "Serif fonts support multiple languages; Sans-Serif do not"], answerIndex: 1, explanation: "'Sans' means 'without' in French. Sans-serif fonts lack the small decorative feet (serifs) on the ends of their letterforms.", example: "Times New Roman is a Serif font; Arial is a Sans-Serif font." },
  { id: 220, category: "UX Laws", difficulty: "Hard", question: "What does 'Postel's Law' (Robustness Principle) state?", options: ["Be conservative in what you do, be liberal in what you accept from others", "The time it takes to make a decision increases with the number of options", "Any system will naturally degrade in usability over time", "Users prefer sites that load in under 2 seconds"], answerIndex: 0, explanation: "In UX, this means you should be empathetic and flexible to the user's input, but strictly reliable in the system's output.", example: "A form that accepts phone numbers typed as '1234567890', '(123) 456-7890', or '123-456-7890' and formats it correctly automatically." },
  { id: 221, category: "Interaction Design", difficulty: "Easy", question: "What is a 'Call to Action' (CTA)?", options: ["A legal disclaimer at the bottom of a page", "An element, usually a button or link, designed to prompt the user to take a specific action", "An audio alert that plays when an error occurs", "A script that tracks user clicks"], answerIndex: 1, explanation: "A CTA guides the user towards the primary goal of the page.", example: "A large, bright button that says 'Start your free trial'." },
  { id: 222, category: "UX Research", difficulty: "Medium", question: "What is a 'Diary Study' in UX?", options: ["A method where designers log their daily progress on a project", "A qualitative research method where users log their thoughts, activities, and interactions with a product over a period of time", "A tool for scheduling user interviews", "A post-mortem analysis of a failed product launch"], answerIndex: 1, explanation: "Diary studies gather data about user behaviors and experiences in their natural environment over days or weeks.", example: "Asking users to record a short video every time they use their smart home system over a two-week period." },
  { id: 223, category: "Gestalt", difficulty: "Hard", question: "Which Gestalt principle explains why we read text organized into paragraphs as distinct blocks of thought?", options: ["Continuity", "Common Fate", "Proximity", "Symmetry"], answerIndex: 2, explanation: "The Law of Proximity states that objects placed close together are perceived as a group. The space between paragraphs groups the lines within them.", example: "Adding margins between paragraphs so the text doesn't look like one giant, intimidating wall of words." },
  { id: 224, category: "Visual Design", difficulty: "Easy", question: "What is 'Visual Hierarchy'?", options: ["The organizational chart of the design team", "The arrangement of elements in a way that implies importance, guiding the user's eye through the layout", "A file naming convention for design assets", "The process of making all elements on a screen the exact same size"], answerIndex: 1, explanation: "Visual hierarchy uses size, color, contrast, and placement to tell the user what to look at first, second, and third.", "example": "Making the headline the largest, boldest text on the page, with a smaller subheadline below it." },
  { id: 225, category: "Information Architecture", difficulty: "Medium", question: "What is 'Card Sorting' primarily used to discover?", options: ["The optimal color palette for a brand", "How users conceptualize and group information, informing the navigation structure", "The fastest sorting algorithm for a database", "Which credit cards users prefer for payment"], answerIndex: 1, explanation: "Card sorting helps designers understand the user's mental model by having them group topics into categories that make sense to them.", example: "Having users group 50 different grocery items into categories to design a supermarket app's navigation menu." },
  { id: 226, category: "Accessibility", difficulty: "Hard", question: "What is the purpose of ARIA (Accessible Rich Internet Applications) attributes?", options: ["To automatically translate web pages into different languages", "To provide additional semantic information to assistive technologies about dynamic content and advanced UI controls", "To enforce strict CSS styling rules", "To compress images for faster loading"], answerIndex: 1, explanation: "ARIA attributes bridge the gap when standard HTML elements can't accurately describe the state or role of complex, JavaScript-driven UI components to screen readers.", example: "Using `aria-expanded='true'` to tell a screen reader that a dropdown menu is currently open." },
  { id: 227, category: "UX Strategy", difficulty: "Medium", question: "What is a 'KPI' in the context of UX?", options: ["Key Programming Interface", "Known Problem Issue", "Key Performance Indicator", "Knowledge Process Integration"], answerIndex: 2, explanation: "A KPI is a measurable value that demonstrates how effectively a company is achieving key business objectives. UX KPIs measure user behavior.", example: "Tracking the 'Task Success Rate' or 'Average Time on Page' as KPIs for a new feature." },
  { id: 228, category: "UI Components", difficulty: "Easy", question: "What is an 'Accordion' UI pattern?", options: ["A musical instrument plugin for web audio", "A vertically stacked list of items that expand and collapse to reveal or hide content associated with them", "A menu that expands horizontally across the top of the screen", "A responsive grid layout that squishes together on small screens"], answerIndex: 1, explanation: "Accordions are useful for condensing large amounts of information into scanable headers, allowing users to drill down into details they care about.", example: "A Frequently Asked Questions (FAQ) page where clicking a question expands it to show the answer." },
  { id: 229, category: "UX Laws", difficulty: "Medium", question: "What is the 'Halo Effect' in user perception?", options: ["The glowing drop shadow applied to active buttons", "A cognitive bias where a user's overall positive impression of a brand influences their feelings about its specific products or features", "The temporary blindness caused by transitioning from dark mode to light mode", "The tendency for users to focus only on the center of the screen"], answerIndex: 1, explanation: "If a user likes a company's aesthetic or brand values, they are more likely to perceive the product as easy to use, even if it has usability flaws.", example: "Assuming a new Apple product will be intuitive and high-quality simply because it is made by Apple." },
  { id: 230, category: "Prototyping", difficulty: "Hard", question: "What does 'Fidelity' refer to in prototyping?", options: ["The degree of exactness or detail with which a prototype reproduces the final product's appearance and functionality", "The loyalty of a user to a specific brand", "The audio quality of user testing recordings", "The strictness of adhering to a design system"], answerIndex: 0, explanation: "Fidelity ranges from low (paper sketches) to high (clickable, pixel-perfect digital mockups).", example: "Moving from a low-fidelity wireframe in Balsamiq to a high-fidelity interactive prototype in Figma." },
  { id: 231, category: "UX Research", difficulty: "Easy", question: "What is an 'Empathy Map'?", options: ["A geographic map showing where users live", "A collaborative tool used to articulate what is known about a particular type of user (Says, Thinks, Does, Feels)", "A survey that asks users how empathetic they are", "A heatmap showing where users clicked the most"], answerIndex: 1, explanation: "Empathy maps help teams build a shared understanding of the user's needs, behaviors, and emotional state.", example: "Plotting user quotes under 'Says' and observed actions under 'Does' after an interview." },
  { id: 232, category: "Visual Design", difficulty: "Medium", question: "In grid systems, what are 'Gutters'?", options: ["The outer margins of the page", "The horizontal baselines for typography", "The empty spaces or gaps between the columns in a grid", "The areas where advertisements are placed"], answerIndex: 2, explanation: "Gutters separate content into distinct columns, preventing text and elements from running into each other.", example: "Setting a 24px gutter between a 12-column grid layout to ensure cards don't touch." },
  { id: 233, category: "Typography", difficulty: "Hard", question: "What is 'Leading' (pronounced ledding) in typography?", options: ["The most prominent headline on a page", "The vertical distance between baselines of successive lines of type", "The tracking applied to the first letter of a paragraph", "The direction a font slants (italics)"], answerIndex: 1, explanation: "Also known as line height in CSS, proper leading improves readability by giving lines of text room to breathe.", example: "Setting the line-height of body text to 1.5 times the font size for comfortable reading." },
  { id: 234, category: "Usability Testing", difficulty: "Medium", question: "What is the 'Think-Aloud Protocol'?", options: ["A feature that reads text on the screen to the user", "A method where test participants are asked to verbalize their thoughts, feelings, and actions as they interact with a product", "A brainstorming session for the design team", "An automated tool that guesses user intent"], answerIndex: 1, explanation: "Thinking aloud gives researchers valuable insights into the user's cognitive processes, expectations, and moments of confusion.", example: "A user saying, 'I expect this button to save my profile, but it took me back to the home page' during a test." },
  { id: 235, category: "Interaction Design", difficulty: "Easy", question: "What is 'Feedback' in interaction design?", options: ["The user review submitted on the app store", "The system's response to a user's action, communicating the result of that action", "The annoying screech from a microphone placed too close to a speaker", "The survey presented after uninstalling an app"], answerIndex: 1, explanation: "Feedback confirms to the user that their action was recognized and tells them what the system is doing as a result.", example: "A button changing color when clicked and a toast message saying 'Settings Saved'." },
  { id: 236, category: "Information Architecture", difficulty: "Medium", question: "What is a 'Sitemap'?", options: ["A map of the physical server locations", "A visual representation or hierarchical diagram of a website's structure and pages", "A detailed plan of the UI color scheme", "A list of all external links pointing to the website"], answerIndex: 1, explanation: "Sitemaps help designers and developers understand the relationships between pages and the overall scope of the content.", example: "A tree diagram showing the Home page branching into About Us, Services, and Contact pages." },
  { id: 237, category: "UX Strategy", difficulty: "Hard", question: "What is a 'Service Blueprint'?", options: ["A technical schematic for database architecture", "A diagram that visualizes the relationships between different service components (people, props, processes) across the entire customer journey, including backstage actions", "A strict set of UI guidelines provided by the client", "A pricing model for SaaS products"], answerIndex: 1, explanation: "While a journey map focuses on the user experience, a service blueprint maps out the internal organizational processes that make that experience possible.", example: "Mapping out exactly what happens in the kitchen (backstage) when a user places an order on a restaurant app (frontstage)." },
  { id: 238, category: "UI Components", difficulty: "Medium", question: "What is a 'Stepper' component?", options: ["A fitness app feature that counts walking steps", "A UI control that displays progress through a sequence of logical and numbered steps", "A button that increases a numerical value by one", "A tool for debugging code line by line"], answerIndex: 1, explanation: "Steppers keep users informed about where they are in a multi-part process, reducing anxiety and abandonment.", example: "A checkout flow showing: 1. Cart > 2. Shipping > 3. Payment > 4. Review." },
  { id: 239, category: "Gestalt", difficulty: "Easy", question: "What does the Gestalt principle of 'Figure/Ground' refer to?", options: ["The financial cost of a design versus its foundational value", "The human eye's ability to separate an object (figure) from its surrounding background (ground)", "The ratio of images to text on a page", "The relationship between mobile and desktop designs"], answerIndex: 1, explanation: "Clear figure/ground separation ensures users know what they are supposed to focus on versus what is background decoration.", example: "A modal window that uses a dark semi-transparent overlay to push the background page out of focus." },
  { id: 240, category: "UX Laws", difficulty: "Medium", question: "What is 'Hofstadter's Law'?", options: ["It always takes longer than you expect, even when you take into account Hofstadter's Law", "Users always prefer the simplest solution", "The first idea is always the worst idea", "Performance decreases exponentially as feature count increases"], answerIndex: 0, explanation: "This self-referential adage is a warning about the difficulties of accurately estimating the time it will take to complete complex tasks, like software development or UX research.", example: "Estimating a redesign will take two weeks, and it ending up taking two months." },
  { id: 241, category: "Accessibility", difficulty: "Easy", question: "What is 'Color Blindness' (Color Vision Deficiency) and how does it impact UX?", options: ["The inability to see any colors at all; everything is black and white", "A decreased ability to see color or differences in color, meaning designers shouldn't rely solely on color to convey meaning", "A preference for monochrome design aesthetics", "A hardware issue with older monitors displaying inaccurate colors"], answerIndex: 1, explanation: "Because a significant portion of users have color vision deficiencies (like red-green color blindness), critical information must use secondary indicators like icons or text.", example: "Adding an 'X' icon and the word 'Error' next to a red error message, instead of just making the text red." },
  { id: 242, category: "UX Research", difficulty: "Medium", question: "What is the difference between a 'Persona' and an 'Archetype'?", options: ["Personas are for B2B products; Archetypes are for B2C", "Personas represent specific fictional users with names and demographics; Archetypes focus broader patterns of behavior and motivations across user groups", "Personas are created by marketing; Archetypes are created by engineering", "There is no difference; the terms are interchangeable"], answerIndex: 1, explanation: "Archetypes categorize users by their behavioral goals (e.g., 'The Bargain Hunter'), while personas put a specific face and story to those behaviors (e.g., 'Sally, a 34-year-old mother of two').", example: "Using archetypes to map out general workflows, then using personas to test specific emotional responses." },
  { id: 243, category: "Visual Design", difficulty: "Hard", question: "What is 'Skeuomorphism' in UI design?", options: ["A modern design trend focusing on flat colors and sharp edges", "A design concept of making items represented resemble their real-world counterparts", "The use of skeletal loading screens", "A method of hiding UI elements until the user hovers over them"], answerIndex: 1, explanation: "Skeuomorphism helps users understand how to interact with digital objects by making them look like familiar physical objects.", example: "The early iPhone 'Notes' app that looked like a yellow legal pad with leather binding." },
  { id: 244, category: "Typography", difficulty: "Medium", question: "What is 'Tracking' in typography?", options: ["Following a user's eye movements across the text", "The uniform adjustment of spacing across a block of text or a word", "The process of pairing two different fonts together", "The height of the lowercase letters relative to uppercase letters"], answerIndex: 1, explanation: "Unlike kerning (which adjusts space between specific pairs of letters), tracking adjusts the overall spacing uniformly across all characters in a selection.", example: "Increasing the tracking on uppercase headlines to give them a more airy, sophisticated look." },
  { id: 245, category: "Interaction Design", difficulty: "Easy", question: "What is a 'Hover State'?", options: ["A mental state where the user is confused and waiting for help", "The visual feedback an interactive element provides when a user places their cursor over it", "A drone delivery feature in an e-commerce app", "The time it takes for a page to load completely"], answerIndex: 1, explanation: "Hover states indicate to desktop users that an element is interactive and clickable.", example: "A button slightly changing color and gaining a drop shadow when the mouse pointer moves over it." },
  { id: 246, category: "Usability Testing", difficulty: "Medium", question: "What is a 'Heuristic Evaluation'?", options: ["Testing a product with real users in a lab setting", "An inspection method where UX experts review a user interface against a set of accepted usability principles", "A statistical analysis of server logs", "An automated tool that checks for broken links"], answerIndex: 1, explanation: "Before spending money on user testing, experts can use heuristics (rules of thumb, like Nielsen's 10) to catch obvious usability flaws.", example: "An expert noting that a system fails the 'Visibility of System Status' heuristic because there is no loading spinner." },
  { id: 247, category: "UX Strategy", difficulty: "Medium", question: "What is 'Scope Creep'?", options: ["The slow transition of a user's mouse across the screen", "The continuous and uncontrolled growth or changes in a project's scope after the project begins", "A gradual increase in the product's price", "A stealthy competitor entering the market"], answerIndex: 1, explanation: "Scope creep happens when new features and requirements keep getting added, threatening timelines and budgets.", example: "Starting a project to build a simple task list, and ending up building a full project management suite with chat and video calling." },
  { id: 248, category: "UI Components", difficulty: "Hard", question: "What is a 'Snackbar' (or Toast) component?", options: ["A section of an app where users can order food", "A small, temporary notification that appears at the edge of the screen to provide feedback about an operation", "A permanent toolbar fixed to the bottom of the screen", "A pop-up advertisement that covers the entire content"], answerIndex: 1, explanation: "Snackbars provide brief messages about app processes without interrupting the user's experience.", example: "A small message popping up at the bottom of the screen saying 'Message archived' with an 'Undo' action." },
  { id: 249, category: "Gestalt", difficulty: "Medium", question: "What is the Gestalt principle of 'Closure'?", options: ["Ensuring users log out safely", "The brain's tendency to perceive incomplete shapes or patterns as complete whole objects", "The process of finalizing a design handoff to developers", "The satisfaction a user feels when completing a purchase"], answerIndex: 1, explanation: "Humans prefer complete shapes, so our minds will fill in missing visual information to create a recognizable pattern.", example: "The famous IBM logo, which consists of disconnected horizontal lines that the brain perceives as solid letters." },
  { id: 250, category: "UX Laws", difficulty: "Easy", question: "What is 'Fitts's Law' primarily concerned with?", options: ["The time required to rapidly move to a target area is a function of the ratio between the distance to the target and the width of the target", "Users prefer familiar interfaces", "People can only hold 7 items in their working memory", "The emotional peak of an experience dictates how it's remembered"], answerIndex: 0, explanation: "Make important interactive targets (like buttons) large and close to where the user's cursor or thumb naturally rests.", example: "Making the 'Add to Cart' button large and placing it near the bottom of a mobile screen for easy thumb reach." },
  { id: 251, category: "UX Research", difficulty: "Medium", question: "What is the primary goal of a 'Competitor Analysis' in UX?", options: ["To steal intellectual property from rival companies", "To identify the strengths and weaknesses of current products in the market to find opportunities for innovation", "To determine the marketing budget of competitors", "To copy the exact visual design of the market leader"], answerIndex: 1, explanation: "Competitor analysis helps teams understand the landscape, establish a baseline for performance, and identify gaps in the market.", example: "Analyzing 5 different food delivery apps to see how many steps it takes to place an order in each." },
  { id: 252, category: "Information Architecture", difficulty: "Hard", question: "What is 'Progressive Disclosure'?", options: ["Revealing trade secrets to the public slowly", "A technique where advanced or rarely used features are initially hidden and revealed only when the user needs them", "A method of slowly loading images on a webpage", "Continuously asking users for more personal information over time"], answerIndex: 1, explanation: "Progressive disclosure reduces cognitive load by keeping the initial interface simple while still providing power features for advanced users.", example: "An 'Advanced Settings' button that expands to show complex configuration options." },
  { id: 253, category: "Visual Design", difficulty: "Easy", question: "What does 'Contrast' achieve in a UI?", options: ["It makes the file size larger", "It differentiates elements from one another, improving readability and drawing attention to key areas", "It blends elements together so they look like one image", "It ensures the application works offline"], answerIndex: 1, explanation: "High contrast (like black text on a white background) is essential for legibility and visual hierarchy.", example: "Using a bright yellow button on a dark navy background to make it pop." },
  { id: 254, category: "UX Laws", difficulty: "Medium", question: "What is 'Hick's Law'?", options: ["The time it takes to make a decision increases with the number and complexity of choices", "Users spend most of their time on other websites, so your site should work like them", "Every action has an equal and opposite reaction", "People remember uncompleted tasks better than completed ones"], answerIndex: 0, explanation: "Hick's Law dictates that you shouldn't overwhelm users with too many options at once, as it leads to decision paralysis.", example: "Limiting a top navigation menu to 5 main categories instead of 20." },
  { id: 255, category: "Prototyping", difficulty: "Medium", question: "What is a 'Wireframe'?", options: ["A physical frame made of wire used in hardware design", "A low-fidelity, simplified outline of a webpage or app, focusing on structure, layout, and functionality rather than visual styling", "A high-fidelity, interactive, and colorful prototype", "The underlying database structure"], answerIndex: 1, explanation: "Wireframes are the 'blueprints' of design, establishing the skeleton of the interface before any visual design (colors, fonts, images) is applied.", example: "Drawing boxes and placeholder text to decide where the header, sidebar, and main content will go." },
  { id: 256, category: "Accessibility", difficulty: "Hard", question: "What is the purpose of 'Focus States'?", options: ["To help users meditate", "To visually indicate which interactive element currently has keyboard focus, essential for users navigating without a mouse", "To blur the background when a modal is open", "To track where the user's eyes are looking on the screen"], answerIndex: 1, explanation: "Focus states (often a glowing outline around a button or link) tell keyboard and screen reader users where they currently are on the page.", example: "A blue ring appearing around a text input field when you press the 'Tab' key to navigate to it." },
  { id: 257, category: "Interaction Design", difficulty: "Medium", question: "What are 'Microinteractions'?", options: ["Interactions that happen extremely quickly", "Small, contained product moments that revolve around a single use case, often providing subtle feedback or delight", "Conversations between junior designers", "Interactions on mobile devices only"], answerIndex: 1, explanation: "Microinteractions are the functional animations and details that make an interface feel alive and responsive.", example: "The 'Like' button turning red and a tiny heart popping out when clicked." },
  { id: 258, category: "UX Strategy", difficulty: "Hard", question: "What does 'Lean UX' focus on?", options: ["Reducing the file size of the CSS to under 100kb", "A design process focused on obtaining feedback early and often, minimizing heavy documentation, and iterating rapidly", "Designing interfaces for people looking to lose weight", "Eliminating all animations to speed up development"], answerIndex: 1, explanation: "Lean UX prioritizes learning and outcomes over rigid deliverables, encouraging cross-functional collaboration.", example: "Building a quick prototype in a day and testing it with users tomorrow, rather than spending a month writing a 100-page specification document." },
  { id: 259, category: "Typography", difficulty: "Easy", question: "What is 'Hierarchy' in typography?", options: ["The ranking of designers in an agency", "Using different font sizes, weights, and styles to organize text and guide the reader's eye", "The alphabetical order of font names", "Using only uppercase letters for important text"], answerIndex: 1, explanation: "Typographic hierarchy tells the reader what to read first, second, and third by making the most important text visually prominent.", example: "An H1 headline being 32px and bold, while the paragraph below it is 16px and regular weight." },
  { id: 260, category: "UX Laws", difficulty: "Medium", question: "What is 'Jakob's Law'?", options: ["Users spend most of their time on other sites, so they expect your site to work the same way as all the other sites they already know", "The simplest explanation is usually the correct one", "Work expands to fill the time available for its completion", "You cannot test your own design objectively"], answerIndex: 0, explanation: "Coined by Jakob Nielsen, this law emphasizes the importance of using established mental models and design conventions.", example: "Placing the logo in the top left corner that links back to the home page, because that's what users expect." },
  { id: 261, category: "UI Components", difficulty: "Easy", question: "What is a 'Tooltip'?", options: ["A tip jar for designers", "A brief, informative message that appears when a user hovers over, focuses on, or touches an element", "A specialized wrench used in hardware repair", "The bar at the top of a browser window"], answerIndex: 1, explanation: "Tooltips provide contextual help or explain the function of an icon without cluttering the UI with permanent text.", example: "Hovering over a floppy disk icon and seeing a small 'Save document' text bubble appear." },
  { id: 262, category: "Gestalt", difficulty: "Hard", question: "What does the Gestalt principle of 'Common Region' state?", options: ["Users from the same country have similar preferences", "Elements tend to be perceived into groups if they are sharing an area with a clearly defined boundary", "Designs should use common shapes like squares and circles", "Elements moving in the same direction are perceived as related"], answerIndex: 1, explanation: "Adding a border or background color around a group of elements strongly unites them in the user's mind, even if they are spaced apart.", example: "Grouping related settings together inside a card with a subtle grey background." },
  { id: 263, category: "UX Research", difficulty: "Medium", question: "What is a 'Quantitative' research method?", options: ["Research that focuses on opinions, feelings, and motivations", "Research that focuses on gathering measurable data and numbers to uncover patterns or test hypotheses", "Research conducted by reading books", "Research that requires a large quantity of designers"], answerIndex: 1, explanation: "Quantitative research answers 'how many' and 'how much', often involving large sample sizes to achieve statistical significance.", example: "Looking at Google Analytics to see that 45% of users drop off at the payment screen." },
  { id: 264, category: "Visual Design", difficulty: "Medium", question: "What is the primary purpose of a 'Mood Board'?", options: ["To track the emotional state of the team", "A collage of images, fonts, colors, and textures used to establish the visual direction and 'feel' of a project before actual design begins", "To complain about clients", "A digital whiteboard for writing code"], answerIndex: 1, explanation: "Mood boards help align stakeholders on the aesthetic vision without wasting time designing specific UI screens.", example: "Collecting images of sleek sports cars, neon lights, and dark metallic textures for a new racing game's UI." },
  { id: 265, category: "Information Architecture", difficulty: "Hard", question: "What is a 'Faceted Navigation' system?", options: ["A 3D navigation menu", "A system that allows users to narrow down search results by applying multiple filters based on different attributes (facets)", "A navigation bar that changes color based on the time of day", "A menu that relies on user facial recognition to open"], answerIndex: 1, explanation: "Faceted search is crucial for e-commerce and large databases, allowing users to drill down into complex data sets.", example: "Shopping for shoes and filtering the results by 'Size: 10', 'Color: Black', and 'Brand: Nike' simultaneously." },
  { id: 266, category: "Accessibility", difficulty: "Easy", question: "Why should you avoid using only color to convey critical information?", options: ["Because color ink is expensive", "Because users with color blindness or low vision might not be able to perceive the difference", "Because it makes the design look messy", "Because colors look different on mobile devices"], answerIndex: 1, explanation: "Information must be accessible to everyone. If a red outline is the only way you indicate an error, a color-blind user might not see it.", example: "Using a red outline AND an error icon AND descriptive text for an invalid password field." },
  { id: 267, category: "Interaction Design", difficulty: "Medium", question: "What is an 'Affordance' in design?", options: ["The price of the software", "A property or feature of an object which presents a prompt on what can be done with it (how it affords interaction)", "The budget allocated for user testing", "The loading speed of a page"], answerIndex: 1, explanation: "Affordances are visual clues in the design that imply how users should interact with something.", example: "A button having a drop shadow makes it look raised, affording pushability (clicking)." },
  { id: 268, category: "UX Laws", difficulty: "Hard", question: "What is the 'Zeigarnik Effect'?", options: ["People remember uncompleted or interrupted tasks better than completed tasks", "The bigger the button, the faster the click", "Users will forgive a bad design if the product is free", "Animations make apps feel faster even if they are slow"], answerIndex: 0, explanation: "This effect explains why progress bars and incomplete checklists are so motivating—our brains hate unfinished business.", example: "A LinkedIn profile completion meter showing 'Your profile is 80% complete' to encourage users to finish setting it up." },
  { id: 269, category: "Usability Testing", difficulty: "Easy", question: "What does it mean to 'Recruit' for a usability study?", options: ["Hiring new designers for the team", "Finding and selecting appropriate participants who represent your target audience to take part in the research", "Drafting soldiers for war", "Gathering data from Google Analytics"], answerIndex: 1, explanation: "Proper recruitment is vital; testing a fitness app on people who never exercise won't yield useful data if your target audience is athletes.", example: "Using a screener survey to find 5 participants who frequently shop online for groceries." },
  { id: 270, category: "UX Strategy", difficulty: "Medium", question: "What is an 'Agile' workflow?", options: ["A gymnastics routine for designers", "An iterative approach to software development and design that emphasizes flexibility, continuous improvement, and rapid delivery in short sprints", "A rigid, linear process where one phase must finish completely before the next begins", "Designing an entire product in one weekend without sleep"], answerIndex: 1, explanation: "Agile teams work in short cycles (sprints), adapting to new requirements and feedback quickly rather than following a strict, unchangeable plan.", example: "Releasing a basic feature, gathering user feedback, and improving it in the next two-week sprint." },
  { id: 271, category: "Typography", difficulty: "Hard", question: "What is the difference between 'Legibility' and 'Readability'?", options: ["Legibility is about code; Readability is about text", "Legibility is how easily individual characters can be distinguished; Readability is how easily blocks of text can be read and understood", "There is no difference; they are synonyms", "Legibility applies to print; Readability applies to digital screens"], answerIndex: 1, explanation: "A font can be highly legible (you can tell the 'a' from the 'e') but poorly readable if the leading is too tight or the line length is too long.", example: "Using a highly legible font like Helvetica, but setting it in all caps, which drastically reduces its overall readability." },
  { id: 272, category: "Visual Design", difficulty: "Easy", question: "What is an 'Icon' in UI design?", options: ["A famous designer", "A visual symbol used to represent a concept, tool, or action, helping users navigate interfaces quickly without reading text", "A religious painting", "A large background image"], answerIndex: 1, explanation: "Icons save screen space and transcend language barriers when used correctly and accompanied by standard mental models.", example: "A magnifying glass symbol universally representing the 'Search' function." },
  { id: 273, category: "Prototyping", difficulty: "Medium", question: "What is an 'Interactive Prototype'?", options: ["A static PDF document", "A mock-up of an interface that allows users to click through screens and simulate real interactions without actual backend code", "A fully functional, launched website", "A physical model built out of cardboard"], answerIndex: 1, explanation: "Interactive prototypes bridge the gap between design and development, allowing teams to test flows before writing expensive code.", example: "Linking screens together in Figma so clicking 'Login' smoothly transitions to the 'Dashboard' screen." },
  { id: 274, category: "Information Architecture", difficulty: "Medium", question: "What is 'Tree Testing'?", options: ["Evaluating the environmental impact of a website", "A usability technique for evaluating the findability of topics in a website's structure (sitemap) without the distraction of visual design", "Testing how fast a webpage loads", "Organizing data structures in a binary tree"], answerIndex: 1, explanation: "Tree testing (often called reverse card sorting) asks users to find specific information by navigating purely through text-based menus.", example: "Asking a user 'Where would you go to change your password?' and watching them navigate a text list of menu options." },
  { id: 275, category: "Gestalt", difficulty: "Easy", question: "What does the Gestalt principle of 'Similarity' mean?", options: ["Designers should copy competitors", "Elements that share visual characteristics (like color, shape, or size) are perceived as related or belonging to the same group", "All buttons should look exactly the same", "Similar fonts should never be paired together"], answerIndex: 1, explanation: "By styling elements identically, you tell the user they share the same function or level of importance.", example: "Making all primary actionable buttons throughout an app the same shade of blue." },
  { id: 276, category: "Accessibility", difficulty: "Medium", question: "What is a 'Screen Reader'?", options: ["A magnifying glass for monitors", "Assistive technology software that reads aloud what is on the computer screen or outputs it to a braille display, primarily used by visually impaired users", "A tool that analyzes the color contrast of a screen", "A device that blocks glare on a laptop"], answerIndex: 1, explanation: "Screen readers rely on proper semantic HTML and ARIA tags to interpret and narrate the structure and content of a web page.", example: "Software like VoiceOver (Mac) or JAWS (Windows) reading the alt text of an image to a blind user." },
  { id: 277, category: "UX Laws", difficulty: "Hard", question: "What is the 'Peak-End Rule'?", options: ["Users only read the top and bottom of a webpage", "People judge an experience largely based on how they felt at its peak (most intense point) and at its end, rather than the total sum or average of every moment", "The highest point of a graph is the most important data", "Designers should put the most important features at the end of a menu"], answerIndex: 1, explanation: "This cognitive bias means that a frustrating process can be salvaged by a delightful ending, or a great experience ruined by a terrible finish.", example: "A complex checkout process that ends with a highly delightful, celebratory 'Order Confirmed' animation." },
  { id: 278, category: "UI Components", difficulty: "Medium", question: "What is a 'Carousel' (or Slider)?", options: ["An amusement park ride", "A UI component that displays multiple items (like images or cards) in a single space, allowing users to swipe or click through them sequentially", "A spinning loading animation", "A circular color picker"], answerIndex: 1, explanation: "Carousels save vertical space on a page, though they are often criticized because users rarely look past the first or second slide.", example: "A hero section on an e-commerce homepage showing three different promotional banners you can click arrows to slide through." },
  { id: 279, category: "UX Research", difficulty: "Easy", question: "What is a 'Qualitative' research method?", options: ["Research focused on gathering subjective insights, behaviors, emotions, and reasons behind user actions", "Research based strictly on numerical data and statistics", "Research conducted to ensure code quality", "A survey with 10,000 respondents answering multiple-choice questions"], answerIndex: 0, explanation: "Qualitative research answers the 'Why' and 'How' of user behavior, often through direct observation or open-ended questions.", example: "Conducting a 1-on-1 interview and asking a user why they abandoned their shopping cart." },
  { id: 280, category: "Interaction Design", difficulty: "Medium", question: "What is a 'Mental Model'?", options: ["A 3D render of a brain", "The belief or expectation a user holds about how a system should work, based on their past experiences", "A strict psychological test given to new hires", "The mathematical formula behind an animation curve"], answerIndex: 1, explanation: "If a system behaves differently than a user's mental model, they will find it confusing and unintuitive.", example: "A user expecting that swiping down on a mobile feed will refresh the content." },
  { id: 281, category: "Visual Design", difficulty: "Hard", question: "What does the term 'Above the Fold' refer to?", options: ["The process of origami", "The portion of a webpage that is visible in a browser window without the user having to scroll down", "Designers who get promoted above senior level", "The hidden code behind a website"], answerIndex: 1, explanation: "Originating from newspaper layouts, it's the prime real estate of a webpage where the most critical value proposition and CTA should live.", example: "Placing the main headline and 'Sign Up' button immediately visible when the page loads, before scrolling." },
  { id: 282, category: "Typography", difficulty: "Medium", question: "What is a 'Baseline' in typography?", options: ["The minimum acceptable quality of a font", "The invisible horizontal line upon which most characters sit and below which descenders extend", "The bottom border of a webpage", "The original unedited version of a text file"], answerIndex: 1, explanation: "Aligning text properly requires understanding the baseline, especially when mixing different font sizes on the same line.", example: "Ensuring the bottom of a capital 'H' and the round bottom of an 'o' rest evenly on the baseline." },
  { id: 283, category: "UX Strategy", difficulty: "Easy", question: "What is a 'Stakeholder'?", options: ["Someone who holds the meat during a barbecue", "Any individual or group that has an interest in or is affected by the outcome of a project (e.g., clients, users, executives, developers)", "A user who has spent money on the app", "A designer who refuses to change their designs"], answerIndex: 1, explanation: "Managing stakeholder expectations and gathering their input is a critical part of UX strategy.", example: "The CEO, the lead engineer, and the marketing director are all stakeholders in the redesign of the company website." },
  { id: 284, category: "Usability Testing", difficulty: "Medium", question: "What does 'Task Success Rate' measure?", options: ["How many tasks a designer completes in a sprint", "The percentage of users who successfully complete a specific assigned task during a usability test", "How fast the server processes a request", "The number of bugs fixed before launch"], answerIndex: 1, explanation: "It is a fundamental usability metric. A low task success rate indicates severe usability issues in a flow.", example: "If 8 out of 10 users successfully found the customer support phone number, the success rate is 80%." },
  { id: 285, category: "UX Laws", difficulty: "Medium", question: "What is 'Miller's Law'?", options: ["The average person can only keep 7 (plus or minus 2) items in their working memory", "Every interface will eventually fail", "You must test with exactly 5 users to find 85% of usability problems", "People prefer symmetry"], answerIndex: 0, explanation: "This psychological law emphasizes why grouping (chunking) information is so important to prevent cognitive overload.", example: "Formatting a phone number as (123) 456-7890 (three chunks) instead of 1234567890 (one ten-digit string)." },
  { id: 286, category: "Information Architecture", difficulty: "Hard", question: "What is a 'Folksonomy'?", options: ["A study of folk music", "A user-generated system of classifying and organizing online content into different categories by the use of metadata (tags)", "A rigid, top-down categorization system created by experts", "The economic impact of user experience"], answerIndex: 1, explanation: "Unlike a strict taxonomy built by site architects, a folksonomy emerges organically from the users themselves.", example: "The hashtag system on Twitter or Instagram, where users invent and apply their own tags to content." },
  { id: 287, category: "UI Components", difficulty: "Easy", question: "What is a 'Breadcrumb Trail'?", options: ["Cookies left by the browser", "A secondary navigation scheme that reveals the user's location in a website or web application hierarchy", "A trail of dust on a dirty monitor", "The path a user's mouse takes across the screen"], answerIndex: 1, explanation: "Breadcrumbs help users understand where they are relative to the rest of the site and allow them to easily navigate back up the hierarchy.", example: "Home > Clothing > Men > Shirts" },
  { id: 288, category: "Accessibility", difficulty: "Medium", question: "What does 'WCAG' stand for?", options: ["Web Content Accessibility Guidelines", "World Computer Action Group", "Wide Color Accurate Graphics", "Web Code Analysis Generator"], answerIndex: 0, explanation: "WCAG provides a shared standard for web accessibility internationally, explaining how to make web content more accessible to people with disabilities.", example: "Following WCAG 2.1 AA standards to ensure a website is legally compliant for accessibility." },
  { id: 289, category: "Gestalt", difficulty: "Hard", question: "What is the Gestalt principle of 'Continuity'?", options: ["A project must be continuously funded", "The human eye is drawn to follow a continuous line or path, preferring to see smooth, unbroken contours rather than abrupt changes", "Users prefer to continue using apps they already know", "A design should be continuous across all devices"], answerIndex: 1, explanation: "Designers use continuity to guide the user's eye smoothly through an interface.", example: "A horizontal carousel where the edge of the next card is partially visible, leading the eye to swipe right." },
  { id: 290, category: "Interaction Design", difficulty: "Medium", question: "What is a 'Signifier'?", options: ["The signature at the bottom of an email", "Any mark or sound, any perceivable indicator that communicates appropriate behavior to a person", "A person who translates sign language", "A legally binding contract"], answerIndex: 1, explanation: "While an affordance is the actual capability of an object, a signifier is the visual cue that tells you that capability exists.", example: "A door handle (affordance: pulling) that has a sign on it saying 'PULL' (signifier)." },
  { id: 291, category: "UX Research", difficulty: "Easy", question: "What is an 'Interview Script'?", options: ["The code that runs the backend of an interview scheduling app", "A prepared document outlining the questions, topics, and structure a researcher intends to cover during a user interview", "A font designed to look like handwriting", "A recording of an interview"], answerIndex: 1, explanation: "An interview script ensures consistency across different interviews while providing a framework to guide the conversation.", example: "A document starting with an introduction, followed by warm-up questions, core tasks, and a wrap-up." },
  { id: 292, category: "Visual Design", difficulty: "Medium", question: "What is 'White Space' (Negative Space)?", options: ["Areas of the design that are colored pure white (#FFFFFF)", "The empty or unmarked space between and around elements of a design layout", "The space outside the computer monitor", "The area reserved for future advertisements"], answerIndex: 1, explanation: "White space is critical for reducing cognitive load, organizing content, and bringing focus to important elements.", example: "The generous empty space around the Google search bar on its minimalist homepage." },
  { id: 293, category: "Prototyping", difficulty: "Hard", question: "What is 'Wizard of Oz' testing?", options: ["Testing a product on users who have never used technology before", "A methodology where a user interacts with a system that they believe to be autonomous, but which is actually being operated entirely or partially by an unseen human", "Testing virtual reality headsets", "A magic trick performed during an interview"], answerIndex: 1, explanation: "This saves massive development time. You can test a 'voice assistant' concept by having a human type the responses behind the scenes.", example: "Testing a chatbot interface where a researcher in another room is manually typing the bot's replies." },
  { id: 294, category: "Information Architecture", difficulty: "Easy", question: "What is 'Navigation' in UX?", options: ["Using a GPS to drive to work", "The system of links, menus, and buttons that allows users to move around a website or application", "Scrolling to the bottom of a page", "The compass icon on a map app"], answerIndex: 1, explanation: "Clear navigation is the backbone of usability; if users can't find what they're looking for, the content doesn't matter.", example: "The 'Hamburger' menu icon in the top corner of a mobile app that opens a drawer of links." },
  { id: 295, category: "Typography", difficulty: "Medium", question: "What is 'Alignment' in text formatting?", options: ["The process of checking if text is politically correct", "The positioning of text relative to the margins (e.g., left, right, center, justified)", "The color contrast of the text against the background", "The translation of text to another language"], answerIndex: 1, explanation: "Consistent alignment creates order. Left-aligned text is generally the easiest to read for long paragraphs in Western languages.", example: "Center-aligning a short headline, but left-aligning the paragraph beneath it for readability." },
  { id: 296, category: "UX Strategy", difficulty: "Hard", question: "What is an 'Experience Map'?", options: ["A map of theme park rides", "A visualization of an entire end-to-end experience that a 'generic' person goes through in order to accomplish a goal, regardless of a specific product or business", "A timeline of a designer's career", "A heat map of mouse clicks"], answerIndex: 1, explanation: "Experience maps look at broad human behavior, while Customer Journey maps focus on the experience with a specific product or company.", example: "Mapping the experience of 'Buying a Home', noting the emotional highs and lows of searching, securing a mortgage, and moving, without focusing on a specific real estate app." },
  { id: 297, category: "UI Components", difficulty: "Medium", question: "What is a 'Toggle Switch'?", options: ["A button that turns the computer on and off", "A UI control that allows users to change a setting between two states (usually On/Off), with the effect taking place immediately", "A hidden developer menu", "A tool for changing CSS themes"], answerIndex: 1, explanation: "Toggles are the digital equivalent of a physical light switch and are ideal for settings that don't require a 'Save' button.", example: "The switch in your phone settings to turn 'Airplane Mode' on or off." },
  { id: 298, category: "UX Laws", difficulty: "Easy", question: "What does 'Aesthetic-Usability Effect' mean?", options: ["Beautiful designs are harder to code", "Users often perceive aesthetically pleasing design as design that's more usable", "Ugly designs are always faster", "Usability is more important than aesthetics"], answerIndex: 1, explanation: "An attractive design creates a positive emotional response, making users more tolerant of minor usability issues.", example: "Users forgiving a slightly confusing menu structure in a highly polished, visually stunning video game interface." },
  { id: 299, category: "Usability Testing", difficulty: "Medium", question: "What is an 'A/B Test'?", options: ["Testing two different user personas", "A randomized experiment with two variants (A and B) to determine which performs better against a given metric", "Testing the front-end (A) and back-end (B) code", "Testing a product on adults (A) and babies (B)"], answerIndex: 1, explanation: "A/B testing provides hard, quantitative data on design decisions rather than relying on opinions.", example: "Showing half your users a green 'Checkout' button and half a red one, and seeing which group completes more purchases." },
  { id: 300, category: "Accessibility", difficulty: "Hard", question: "What is the importance of 'Semantic HTML' in accessibility?", options: ["It makes the code look prettier for other developers", "It uses HTML elements according to their intended purpose (like <nav>, <header>, <button>), which provides critical context to assistive technologies", "It reduces the file size of the HTML document", "It automatically styles the elements with CSS"], answerIndex: 1, explanation: "A `<div>` with an 'onClick' handler is functionally a button to a mouse user, but a screen reader won't know it's a button unless you use the semantic `<button>` tag or ARIA roles.", example: "Using `<nav>` for the navigation menu instead of a generic `<div class='nav'>`." }
];
